logger = logging.getLogger(__name__)

_FLAT_GRID_CAP = 48
_FLAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)
_FLAT_MAX_NUMEL = 2**31 - 1 - 65536
_INT32_LIMIT = 2**31

_ONCT_BLOCK = 32768
_ONCT_GRID_LIMIT = 65535
